namespace IranVsTuran.Localization
{
    public static partial class Strings
    {
        /// <summary>Cutscene lines ("story.&lt;cutscene&gt;.&lt;slide&gt;") and boss battle cries.</summary>
        static readonly string[][] Story =
        {
            new[] { "story.prologue.1", "Long ago, in the age of kings and heroes, the river Jeyhun divided two lands: Iran and Turan.", "روزگاری دور، در دوران شاهان و پهلوانان، رود جیحون دو سرزمین را از هم جدا می‌کرد: ایران و توران." },
            new[] { "story.prologue.2", "The throne of Iran will be mine. Cross the river! Burn every village!", "تخت ایران از آنِ من خواهد شد. از رود بگذرید! هر دهکده‌ای را بسوزانید!" },
            new[] { "story.prologue.3", "Afrasiab's army has reached the Jeyhun. Rostam, my son, the time has come.", "سپاه افراسیاب به کنار جیحون رسیده است. رستم، پسرم، هنگامش رسیده." },
            new[] { "story.prologue.4", "Give me Rakhsh and my grandfather's mace. No Turanian will pass.", "رخش و گرز نیایم را به من بده. هیچ تورانی‌ای از این راه نخواهد گذشت." },
            new[] { "story.prologue.5", "Build towers beside the road and hold the line. Defend Iran!", "در کنار راه برج بساز و راه را ببند. از ایران پاسداری کن!" },

            new[] { "story.invasion_end.1", "Garsivaz fled back across the Jeyhun, and the young Rostam's name spread through the land.", "گرسیوز به آن سوی جیحون گریخت و نام رستمِ جوان در سراسر ایران پیچید." },
            new[] { "story.invasion_end.2", "This is not over. Turan does not forget.", "این پایان کار نیست. توران فراموش نمی‌کند." },

            new[] { "story.haftkhan.1", "Kay Kavus, proud and reckless, marched on Mazandaran, the land of the divs. Now I am a blind prisoner!", "من، کاووس‌شاه، مغرور و بی‌پروا به مازندران، سرزمین دیوان، لشکر کشیدم. اکنون اسیری نابینایم!" },
            new[] { "story.haftkhan.2", "Your king is mine now: blind and in chains, deep in my cave.", "شاه شما اکنون از آنِ من است؛ نابینا و در زنجیر، در ژرفای غار من." },
            new[] { "story.haftkhan.3", "Seven labours lie on the road to Mazandaran. Only you can pass them, Rostam.", "در راه مازندران هفت خوان است. تنها تو از آن‌ها می‌گذری، رستم." },
            new[] { "story.haftkhan.4", "Lions, witches, dragons: let them come. I will bring the king home.", "شیر و جادو و اژدها، بگذار بیایند. شاه را به خانه بازمی‌گردانم." },

            new[] { "story.haftkhan_end.1", "Rostam slew the White Div in the depths of his cave.", "رستم دیو سپید را در ژرفای غارش از پای درآورد." },
            new[] { "story.haftkhan_end.2", "The blood of the div's heart gave the king back his sight, and Mazandaran was free.", "خون جگر دیو چشمان شاه را روشن کرد و مازندران آزاد شد." },
            new[] { "story.haftkhan_end.3", "Rostam, champion of the world: Iran owes you everything.", "رستم، ای جهان‌پهلوان، ایران همه چیزش را مدیون توست." },

            new[] { "story.sohrab.1", "Years later, a young champion led Turan's army against Iran.", "سال‌ها بعد، پهلوانی جوان سپاه توران را به سوی ایران آورد." },
            new[] { "story.sohrab.2", "I am Sohrab. I seek only one man in Iran: my father, whom I have never seen.", "من سهرابم. در ایران تنها یک تن را می‌جویم: پدرم، که هرگز ندیده‌ام." },
            new[] { "story.sohrab.3", "I am Gordafarid. As long as I live, the White Castle will not fall!", "من گردآفریدم. تا من زنده‌ام، دژ سپید فرو نمی‌افتد!" },
            new[] { "story.sohrab.4", "Take the castle. And Sohrab must never learn that Rostam is his father.", "دژ را بگیرید. و سهراب هرگز نباید بداند که رستم پدر اوست." },

            new[] { "story.sohrab_end.1", "Rostam and Sohrab met in single combat, neither knowing the other.", "رستم و سهراب، بی‌آنکه یکدیگر را بشناسند، رو در روی هم ایستادند." },
            new[] { "story.sohrab_end.2", "Whoever you are… my father Rostam will avenge me.", "هر که هستی… پدرم رستم کین مرا خواهد خواست." },
            new[] { "story.sohrab_end.3", "My son! Bring the Nushdaru from the king, quickly!", "پسرم! نوشدارو را از شاه بیاورید، زود!" },
            new[] { "story.sohrab_end.4", "But the Nushdaru came too late. Iran won the war, and Rostam lost his son.", "اما نوشدارو دیر رسید؛ نوشدارو پس از مرگ سهراب. ایران پیروز شد و رستم پسرش را از دست داد." },

            new[] { "story.siavash.1", "Prince Siavash, the purest of heroes, was killed in Turan on Afrasiab's order.", "شاهزاده سیاوش، پاک‌ترین پهلوان، به فرمان افراسیاب در توران کشته شد." },
            new[] { "story.siavash.2", "It is said that where his blood fell, a red plant grew: the blood of Siavash.", "می‌گویند هر جا خونش ریخت، گیاهی سرخ رویید: خون سیاوشان." },
            new[] { "story.siavash.3", "I am the son of Siavash. The time for vengeance has come.", "من پسر سیاوشم. هنگام کین‌خواهی فرا رسیده است." },
            new[] { "story.siavash.4", "To Turan, then. All the way to Gang-Dezh.", "پس به سوی توران؛ تا خودِ گنگ‌دژ." },

            new[] { "story.ending.1", "Gang-Dezh fell. Afrasiab fled, and at last was found hiding in a cave by a lake.", "گنگ‌دژ فرو ریخت. افراسیاب گریخت و سرانجام در غاری کنار دریاچه پیدا شد." },
            new[] { "story.ending.2", "Siavash is avenged. Let there be peace between the rivers.", "کین سیاوش گرفته شد. بگذار میان دو رود آرامش باشد." },
            new[] { "story.ending.3", "And Ferdowsi wrote: “Thirty years I toiled; with this Persian tongue I brought Iran back to life.”", "و فردوسی سرود: «بسی رنج بردم در این سال سی / عجم زنده کردم بدین پارسی»" },
            new[] { "story.ending.4", "Thank you for playing. A new challenge awaits on Mount Damavand…", "سپاس که بازی کردی. چالشی تازه در کوه دماوند در انتظار توست…" },

            new[] { "story.damavand.1", "Long before Rostam, the tyrant Zahhak ruled with two serpents growing from his shoulders.", "سال‌ها پیش از رستم، ضحاکِ ستمگر با دو ماری که بر دوشش روییده بود فرمان می‌راند." },
            new[] { "story.damavand.2", "Kaveh the blacksmith raised his leather apron as a banner, and Fereydun chained Zahhak inside Mount Damavand.", "کاوهٔ آهنگر چرم‌پاره‌اش را درفش کرد و فریدون ضحاک را در دل کوه دماوند به بند کشید." },
            new[] { "story.damavand.3", "The chains are breaking. My serpents are hungry!", "زنجیرها می‌گسلند. مارهایم گرسنه‌اند!" },
            new[] { "story.damavand.4", "Then Damavand will be his prison once more.", "پس دماوند بار دیگر زندانش خواهد شد." },

            new[] { "story.damavand_end.1", "Zahhak was chained again beneath Damavand, and there he remains to this day.", "ضحاک دوباره در دل دماوند به بند کشیده شد و تا امروز همان‌جاست." },

            // Shown when a boss enters the battlefield.
            new[] { "boss.garsivaz", "Afrasiab's brother does not retreat!", "برادر افراسیاب پس نمی‌نشیند!" },
            new[] { "boss.dragon", "A roar shakes the forest…", "غرشی جنگل را می‌لرزاند…" },
            new[] { "boss.divsepid", "Who dares to enter the cave of the White Div?", "کیست که جرئت کرده به غار دیو سپید پا بگذارد؟" },
            new[] { "boss.houman", "Houman of Turan fears no Iranian!", "هومانِ تورانی از هیچ ایرانی‌ای نمی‌هراسد!" },
            new[] { "boss.ashkbus", "The arrows of Ashkbus never miss!", "تیر اشکبوس هرگز به خطا نمی‌رود!" },
            new[] { "boss.akvan", "I am the wind. Who can catch the wind?", "من بادم. باد را که می‌تواند گرفت؟" },
            new[] { "boss.afrasiab", "Turan will never kneel!", "توران هرگز زانو نمی‌زند!" },
            new[] { "boss.zahhak", "Feed my serpents!", "مارهایم را سیر کنید!" },
        };
    }
}
